import{_ as o,o as t,c as n,a5 as e}from"./chunks/framework.BEZBAInb.js";const _=JSON.parse('{"title":"マスコット Kona","description":"","frontmatter":{"title":"マスコット Kona","order":2},"headers":[],"relativePath":"ja/latest/community/kona.md","filePath":"ja/latest/community/kona.md","lastUpdated":1788455378000}'),r={name:"ja/latest/community/kona.md"};function i(l,a,s,c,d,p){return t(),n("div",null,[...a[0]||(a[0]=[e('<h1 id="関連-ip-紹介" tabindex="-1">関連 IP 紹介 <a class="header-anchor" href="#関連-ip-紹介" aria-label="Permalink to &quot;関連 IP 紹介&quot;">​</a></h1><h2 id="kona-について" tabindex="-1">Kona について <a class="header-anchor" href="#kona-について" aria-label="Permalink to &quot;Kona について&quot;">​</a></h2><p>Kona は Konado 専属のマスコットです。<strong>元気でかわいらしく、活発な</strong>少女像を核としており、ブランドビジュアルの重要なシンボルであるだけでなく、ユーザーと Konado を親しみやすくつなぐ存在でもあります。</p><h2 id="kona-のビジュアル" tabindex="-1">Kona のビジュアル <a class="header-anchor" href="#kona-のビジュアル" aria-label="Permalink to &quot;Kona のビジュアル&quot;">​</a></h2><p>Kona は Konado のあらゆる場面に登場します。起動画面、公式サイトのトップページ、製品ドキュメントなど、さまざまな場所でブランドに生き生きとした印象を与えます。Konado のバージョン更新に合わせて Kona の姿も進化し、新バージョンのデザインスタイルに寄り添いながら、細部の作り込みによってより洗練され、識別しやすいデザインになっていきます。</p><p>通常、Konado の<strong>メジャーバージョン更新</strong>では、Kona の新しい専用ビジュアルが公開されます。どのビジュアルにも独自の工夫があり、彼女の核となる魅力を受け継ぎつつ、製品にさらなる楽しさと記憶に残る要素を加えます。</p><p>もちろん、マイナーバージョン更新でも、季節ごとの衣装や小物の追加など、Kona に小さな変化が加わることがあります。これにより、表現はさらに豊かで多彩になります。</p><blockquote><p>イラストレーター：<a href="https://github.com/ioniccrystal" target="_blank" rel="noreferrer">ioniccrystal</a> 公開日：2025-09-15</p></blockquote><p align="center"><img src="https://legacy.godothub.com/kbgirl/kona/kona.png" alt="Kona 2.0 メインビジュアル" width="300"></p>',9)])])}const m=o(r,[["render",i]]);export{_ as __pageData,m as default};
